import React, { ReactNode, forwardRef } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { _useBaseInputContext } from './hooks/useBaseInputContext.js';
import { getTextStyle } from '../../core/utils/styles/text-styles.js';
import { Flex } from '../../layouts-core/flex/Flex.js';

//#region Typings
/** Accepted properties for the Content */
export interface BaseInputContentProps {
  /** Elements to be displayed in the Prefix slot. */
  children: ReactNode;
}
//#endregion

//#region Styled Components
const StyledBaseInputContent = /* @__PURE__ */ styled(Flex)<{
  disabled: boolean;
  $hasError: boolean;
}>(({ disabled, $hasError }) => {
  const color = disabled
    ? Colors.Icon[$hasError ? 'Critical' : 'Neutral'].Disabled
    : $hasError
    ? Colors.Icon.Critical.Default
    : Colors.Icon.Neutral.Subdued;

  return {
    lineHeight: '100%',
    color,
    ...getTextStyle('base'),

    '& svg': {
      boxSizing: 'content-box',
      alignItems: 'stretch',
      fill: color,
    },

    '&:first-child': {
      alignSelf: 'stretch',
    },

    /** Icon component is being used as direct child element */
    '& svg:first-of-type': {
      alignSelf: 'center',
    },
  };
});
//#endregion

/**
 * The BaseInputContent does not expose className / style, because it is only used to determine
 * whether the children should be rendered as prefix or suffix items. The BaseInputContent is then
 * internally used again to wrap only the prefix elements, but not the prefix buttons, which are
 * rendered next to the input container.
 * Adding custom styles would only style the elements wrapped in the internally rendered BaseInputContent
 * container, which would be unexpected, since for the user, the buttons are also wrapped in the container.
 */

/** BaseInputContent component, used for adding elements to the prefix/suffix slot. */
export const BaseInputContent = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  BaseInputContentProps
>((props, forwardedRef) => {
  const { children }: BaseInputContentProps = props;
  const { hasError = false, disabled = false } = _useBaseInputContext();

  return (
    <StyledBaseInputContent
      disabled={disabled}
      $hasError={hasError}
      ref={forwardedRef}
      flexGrow={0}
      alignItems="center"
      alignSelf="stretch"
      gap={8}
      paddingLeft={8}
      paddingRight={8}
    >
      {children}
    </StyledBaseInputContent>
  );
});

/** Component used for adding elements to the prefix slot. */
export const BaseInputPrefix = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  BaseInputContentProps
>((props, forwardedRef) => <BaseInputContent ref={forwardedRef} {...props} />);

/** Component used for adding elements to the suffix slot. */
export const BaseInputSuffix = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  BaseInputContentProps
>((props, forwardedRef) => <BaseInputContent ref={forwardedRef} {...props} />);

(
  BaseInputPrefix as typeof BaseInputPrefix & { displayName: string }
).displayName = 'Input.Prefix';
(
  BaseInputSuffix as typeof BaseInputSuffix & { displayName: string }
).displayName = 'Input.Suffix';
